css:
.loader {
  position: relative;
  width: 54px;
  height: 34px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 50%;
  background: #6366f1;
  animation: wblink 1.4s ease-in-out infinite;
}
.loader i {
  position: absolute;
  bottom: 2px;
  left: 50%;
  border: 4px solid #6366f1;
  border-color: #6366f1 transparent transparent transparent;
  border-radius: 50%;
  box-sizing: border-box;
  transform: translateX(-50%);
  animation: wblink 1.4s ease-in-out infinite;
}
.loader i:nth-child(1) { width: 22px; height: 22px; animation-delay: 0.15s; }
.loader i:nth-child(2) { width: 38px; height: 38px; animation-delay: 0.3s; }
.loader i:nth-child(3) { width: 54px; height: 54px; animation-delay: 0.45s; }
@keyframes wblink {
  0%, 65%, 100% { opacity: 0.2; }
  30% { opacity: 1; }
}
